SELECT DATE_TRUNC('YEAR', sale_date) AS year_start, DATE_TRUNC('MONTH', sale_date) AS activity_month, APPROX_PERCENTILE(units, ARRAY(0.25, 0.5, 0.75)) AS units_quartiles, ROUND(AVG(units), 2) AS avg_units, ROUND(AVG(units), 2) AS avg_units_2, ROUND(AVG(revenue), 2) AS avg_revenue, STDDEV_SAMP(units) AS units_stddev FROM store_sales GROUP BY year_start, activity_month HAVING units_stddev >= 0 ORDER BY units_stddev;
